import {initial,scene,choose,pathName,art} from './engine.mjs';
const $=id=>document.getElementById(id);const key='hannui-first-breath-v1';let state=null,saved=null,storageOk=true;
const escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(parsed.version===1&&typeof parsed.name==='string'&&Array.isArray(parsed.journal)){scene(parsed);saved=parsed;}}}catch{storageOk=false;}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));saved=structuredClone(state);storageOk=true;}catch{storageOk=false;}}
function landing(){state=null;$('app').innerHTML=`<section class="hero flash"><div><p class="eyebrow">HAN NUI · A TEXT ROLE-PLAYING GAME</p><h1>당신의 이름으로,<br><em>첫 숨을 열다.</em></h1><p class="intro">무엇을 쥘 것인가. 어떤 힘을 따를 것인가.<br>아직 정해진 길은 없다.<br>한뉘의 새로운 제자, 당신의 이야기를 시작하세요.</p><form id="start" class="name-form"><label for="name">이야기에 남길 이름</label><input id="name" name="name" maxlength="16" placeholder="제자의 이름을 입력하세요" autocomplete="off" required><p id="name-error" class="error" aria-live="polite"></p><button class="primary wide">새로운 이야기 시작하기 <span aria-hidden="true">↗</span></button><div class="sub-action">${saved?`<button type="button" class="quiet" id="resume">${escape(saved.name)}의 이야기 이어가기 →</button>`:'<span class="muted">선택으로 성장하는 텍스트 RPG · 짧은 서장</span>'}</div></form></div><div class="landscape" role="img" aria-label="달 아래 겹겹의 산과 그 사이로 흐르는 강"><div class="moon"></div><div class="ridge"></div><div class="ridge two"></div><div class="river"></div><div class="ridge three"></div><span class="art-note">한 땅에 흐르는 일곱 결</span></div></section>`;
 $('start').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim();if(!name||name.length>16){$('name-error').textContent='1~16자로 이름을 입력해 주세요.';return;}if(saved){$('new-name').value=name;$('restart').showModal();}else start(name);};if(saved)$('resume').onclick=()=>{state=structuredClone(saved);render();};}
function start(name){state=initial(name);persist();render();}
function bar(label,value,max){return `<div class="stat"><div class="stat-label"><span>${label}</span><span>${value} / ${max}</span></div><div class="bar"><i style="width:${Math.min(100,value/max*100)}%"></i></div></div>`;}
function render(){const data=scene(state);const traits=[['길',pathName(state)],['결',state.element||'아직 드러나지 않음'],['무기 / 매개',state.weapon||'정하지 않음']];$('app').innerHTML=`<div class="game-layout"><aside class="sidebar"><div class="avatar"><span>${escape(state.element?.slice(0,1)||'숨')}</span></div><div class="profile"><h2>${escape(state.name)}</h2><span class="rank">${state.scene==='ending'?'첫 깨달음을 얻은 제자':'여울원의 신입 제자'}</span></div><div class="rule"></div><div>${traits.map(([k,v])=>`<div class="trait"><span>${k}</span><span>${v}</span></div>`).join('')}</div><div class="rule"></div><div>${bar('체력',state.hp,10)}${bar('사용 가능한 숨',state.energy,6)}</div><div class="rule"></div><div><p class="eyebrow sidebar-label">쌓아 온 것</p>${[['제어',state.control],['숙련',state.skill],['통찰',state.insight],['이솔의 신뢰',state.trust]].map(([k,v])=>`<div class="trait"><span>${k}</span><span>${v}</span></div>`).join('')}</div><div class="rule"></div><div class="tags"><span class="tag">${state.path==='inner'?'무인':state.path==='outer'?'마법사':'빈 몸'}</span>${state.flags.includes('advantage')?'<span class="tag">위기 선점</span>':''}${state.flags.includes('isol-injured')?'<span class="tag">이솔 부상</span>':''}</div></aside><article class="story flash"><div class="chapter-nav"><span>서장 · 첫 번째 숨 / ${['','이름과 길','수련의 날들','첫 번째 시련','당신의 발자국'][data.chapter]}</span><span class="dots" aria-label="4장 중 ${data.chapter}장">${[1,2,3,4].map(n=>`<i class="${n<=data.chapter?'active':''}"></i>`).join('')}</span></div>${state.last?`<div class="notice" role="status">${escape(state.last)}</div>`:''}<p class="eyebrow">CHAPTER 0${data.chapter}</p><h1 tabindex="-1" id="scene-title">${data.title}</h1><div class="prose">${data.text.map(t=>`<p>${escape(t)}</p>`).join('')}</div>${data.quote?`<blockquote class="quote">${data.quote}</blockquote>`:''}${state.scene==='ending'?ending():`<div class="choice-caption">YOUR CHOICE · 당신의 선택</div><div class="choices">${data.choices.map((c,i)=>`<button class="choice" data-choice="${c.id}" ${c.disabled?'disabled':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span><strong>${escape(c.title)}</strong><small>${escape(c.hint)}</small></span><span class="arrow" aria-hidden="true">↗</span></button>`).join('')}</div>`}<div class="story-bottom"><span class="saved">${storageOk?'이 브라우저에 자동 저장됨':'자동 저장 불가 · 현재 창에서 계속 플레이할 수 있습니다'}</span><button class="quiet" id="home">처음 화면으로</button></div><details class="journal"><summary>여정의 기록 · ${state.journal.length}개의 선택</summary><ol>${state.journal.map(j=>`<li><span>${escape(j.scene)}</span> — ${escape(j.choice)}</li>`).join('')}</ol></details></article></div>`;
 document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state=choose(state,b.dataset.choice);persist();render();});$('home').onclick=landing;if($('download'))$('download').onclick=download;if($('replay'))$('replay').onclick=()=>{$('new-name').value=state.name;$('restart').showModal();};$('scene-title').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function ending(){return `<div class="result-grid"><div><small>당신이 연 길</small><strong>${pathName(state)}</strong></div><div><small>첫 기술</small><strong>${art(state)}</strong></div><div><small>마을에 남긴 기억</small><strong>${{together:'함께 지킨 약속',child:'작은 생명의 은인',herbs:'약을 지킨 제자'}[state.ending]}</strong></div><div><small>다음 이야기의 씨앗</small><strong>${state.trust>=2?'믿을 수 있는 동료':'아직 남은 거리'}</strong></div></div><p class="muted">서장 끝 · 현재 시제품은 여기까지 플레이할 수 있습니다. 다른 길과 무기로 새로운 이야기를 만들어 보세요.</p><div class="sub-action"><button class="primary" id="download">여정 기록 내려받기</button><button class="quiet" id="replay">다른 제자로 시작하기 →</button></div>`;}
function download(){const text=`한뉘 · 첫 번째 숨\n${state.name}의 여정\n${pathName(state)} / ${state.element} / ${state.weapon}\n첫 기술: ${art(state)}\n\n`+state.journal.map((j,i)=>`${i+1}. ${j.scene}\n   ${j.choice}`).join('\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='한뉘-여정.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.body.insertAdjacentHTML('beforeend','<dialog id="restart"><h2>새로운 이야기를 시작할까요?</h2><p>현재 브라우저에 저장된 여정이 새 제자의 이야기로 바뀝니다.</p><input type="hidden" id="new-name"><div class="sub-action"><button class="primary" id="confirm-restart">새로 시작하기</button><button class="quiet" id="cancel-restart">돌아가기</button></div></dialog>');
$('confirm-restart').onclick=()=>{const name=$('new-name').value;$('restart').close();start(name);};$('cancel-restart').onclick=()=>$('restart').close();$('help').onclick=()=>$('guide').showModal();$('close-guide').onclick=()=>$('guide').close();$('brand').onclick=e=>{e.preventDefault();landing();};landing();
